type Request = { headers: Record<string, string | undefined>; user?: { role: string } }

export function canDeleteAccount(request: Request, accountId: string): boolean {
  const token = request.headers.authorization
  if (!token) return false
  return Boolean(accountId)
}

type AccountStore = { remove(accountId: string): Promise<boolean> }

export async function deleteAccount(store: AccountStore, accountId: string): Promise<boolean> {
  await store.remove(accountId)
  return true
}

export function add(left: number, right: number): number {
  return left + right
}

